'use strict';
function journeyStage(){return state.phase==='forest'?0:['plan','receipt'].includes(state.phase)?1:['logistics','logisticsReceipt'].includes(state.phase)?2:3;}
function renderJourneyNav(){const nav=document.getElementById('journeyNav');if(!state.journey){nav.innerHTML='';return;}const current=journeyStage(),done=state.phase==='result';nav.innerHTML=`<ol class="journey-nav" aria-label="Dein Weg vom Wald zum Vertragsabschluss">${[['Waldplanung','Auftrag & Vorbereitung'],['Holzernte','Vier Maschinenschichten'],['Logistik','Polter bis Werk'],['Abrechnung & Vertrag','Mengen prüfen & abschließen']].map(([name,sub],i)=>`<li class="${i<current||done?'complete':i===current?'current':''}" ${i===current?'aria-current="step"':''}><span class="journey-number">${i<current||done?'✓':i+1}</span><div><b>${name}</b><small>${sub}</small></div></li>`).join('')}</ol>`;}
function journeyHeading(title,text){return `<div class="intro journey-intro"><div><p class="eyebrow">CFHarvest · INTERFORST · ${journeyStage()+1} / 4</p><h1>${title}</h1><p>${text}</p></div><span class="journey-id">${state.journey.contract?.id||ForestJourney.contracts[state.journey.contractType].id}</span></div>`;}
// Decision toggles. Each option: [value, short title, one-line reason]. German source text; translations.tsv supplies English and French.
const choiceOptions={
 game:{
  handoverMode:[['manual','Manuell','Revierleitung fährt vor Ort'],['digital','Digital','Bestätigter Auftrag an Bord']],
  forwardStart:[['early','Sofort','Volle Schicht gebucht'],['stock','Nach Holzbestand','Startet bei rückbarem Holz'],['late','Ab Stunde 4','Später Start, weniger Leerlauf']],
  reporting:[['manual','Am Schichtende','Disposition sieht Bestand spät'],['live','Laufend','Aktuelle Mengen für Disposition']],
  cutting:[['cached','Geladene Einstellung','Schnell, evtl. veraltet'],['current','Auftrag prüfen','Verhindert falsche Längen']],
  quality:[['skip','Keine Kontrollmessung','Kein Zusatzaufwand'],['check','Kontrollmessung','Deckt Fehleinstellung früh auf']],
  pace:[['careful','Schonend','Schont den Boden'],['normal','Normal','Referenztempo'],['fast','Volllast','Belastet Boden bei Nässe']],
  boundary:[['field','Papierkarte + Abgleich','Grenze vor Ort geklärt'],['digital','Digital integriert','Geprüfter Hiebsplan an Bord'],['unchecked','Alte Skizze','Ostgrenze unklar']],
  survey:[['protect','Teilfläche aussparen','Sicher, aber weniger Leistung'],['inspect','Nacherkundung','Lücke vor Ort schließen'],['ignore','Trotzdem bearbeiten','Schaden und Hiebsperre möglich']],
  priority:[['normal','Keine Zusage','Kein Zusatzauftrag'],['express','180 fm zusagen','Bonus nur bei Erfüllung']]},
 journey:{
  contractType:[['standard','Standard','Sichere Zusage, kleiner Ausgleich'],['premium','Mehrmenge','Mehr Erlös, höheres Fehlmengenrisiko']],
  preparation:[['records','Aktenstand übernehmen','Lücken bleiben offen'],['field','Vor Ort prüfen','Grenze und Erkundung geklärt']],
  documentation:[['paper','Papier und Telefon','Übergabe bindet Revierzeit'],['digital','Digitaler Auftrag','Live-Meldungen, Übergabe bestätigen']],
  haulMode:[['matched','Nach Polterbestand','Passende Tourenzahl'],['estimate','Pauschal','Nach Vertragsmenge, evtl. Leertouren']],
  access:[['checked','Zufahrt prüfen','Wendepunkte vorab frei'],['unchecked','Ungeprüft','Talgrund-Zufahrt evtl. ungeeignet']],
  deliveryDocs:[['linked','Verknüpfen','Herkunft lückenlos belegt'],['paper','Papierliste','Herkunft nur auf Papier']],
  reconciliation:[['match','Belege prüfen','Strittige Menge wird abgerechnet'],['accept','Werkzuordnung übernehmen','Spart Prüfung, Erlös bleibt offen']],
  closeout:[['document','Dokumentieren','Restaufgaben nachvollziehbar übergeben'],['force','Als erledigt melden','Unbelegt bei offenen Restmengen']]}};
// Direct € = change of the stage's certain planned cost against a reference option, all other choices as currently set.
// Switching from A to B therefore moves the live total by exactly cost(A) − cost(B).
const choiceReference={game:{handoverMode:'digital',forwardStart:'early',reporting:'manual',cutting:'cached',quality:'skip',pace:'normal',boundary:'digital',survey:'ignore',priority:'normal'},journey:{contractType:'standard',preparation:'records',documentation:'paper',haulMode:'estimate',access:'unchecked',deliveryDocs:'paper',reconciliation:'accept',closeout:'document'}};
const journeyChoiceStage={contractType:'forest',preparation:'forest',documentation:'forest',haulMode:'logistics',access:'logistics',deliveryDocs:'logistics',reconciliation:'settlement',closeout:'settlement'};
function withChoice(scope,s,key,value){return scope==='journey'?{...s,journey:{...s.journey,[key]:value}}:{...s,[key]:value};}
function plannedCost(scope,s,key){if(scope==='game')return ForestGame.previewCost(s).total;const stage=journeyChoiceStage[key];return stage==='forest'?ForestJourney.planPreview(s).cost:stage==='logistics'?ForestJourney.haulPreview(s).estimate:ForestJourney.settlementPreview(s).cost;}
// The documented closeout is itself a certain cost; every other reference option adds nothing of its own.
function referenceCost(scope,key){return scope==='journey'&&key==='closeout'?-ForestJourney.COSTS.closeout:0;}
// Downgrade exposure of a stale length setting this shift: expected sawlog volume × (saw − downgraded price + resorting), rounded up to 100 €.
function downgradeExposure(s){const G=ForestGame,h=s.stands.find(x=>x.id===s.harvester);if(s.loadedGrade===G.gradeSpec(s)||h.closed)return 0;const hours=Math.max(0,G.HOURS-G.schedule(s).hStart),restricted=h.surveyCoverage<100&&s.survey==='protect'?G.YIELD.protectedArea:1,saw=Math.min(h.remaining,G.YIELD.harvester*h.factor*G.paces[s.pace].factor*restricted*hours)*G.YIELD.sawShare,p=G.targets(s).prices,loss=p.saw-p.down+G.COSTS.resort,amount=s.quality==='check'?G.COSTS.qualityCorrection+Math.min(saw,G.YIELD.correctionVolume)*loss:saw*loss;return Math.ceil(amount/100)*100;}
const percentChange=factor=>Math.round((factor-1)*100);
function choiceMeta(scope,key,value,s=state){
 const G=ForestGame,J=ForestJourney,ref=choiceReference[scope][key],t=withChoice(scope,s,key,value),option=choiceOptions[scope][key].find(x=>x[0]===value);
 const meta={cost:G.round(plannedCost(scope,withChoice(scope,s,key,ref),key)-plannedCost(scope,t,key)+referenceCost(scope,key)),risk:[],rate:null,bonus:null,note:null,reason:option?option[2]:''};
 if(scope==='game'){
  const plan=G.schedule(t),h=t.stands.find(x=>x.id===t.harvester);
  if(key==='forwardStart'&&value==='early')meta.risk.push({value:-G.RATES.forwarder,per:'h',label:'Leerlauf'});
  if(key==='cutting'&&value==='cached'){const exposure=downgradeExposure(t);if(exposure)meta.risk.push({value:-exposure,label:'Abwertung'});}
  if(key==='boundary'&&value==='unchecked'&&h.id==='a'&&!t.boundaryChecked.a&&!h.closed&&h.remaining>0)meta.risk.push({value:-G.COSTS.boundaryIncident,label:'Grenze'});
  if(key==='survey'&&plan.unknown){if(value==='ignore')meta.risk.push({value:-G.COSTS.biotopeIncident,label:'Biotop'});if(value==='protect')meta.note={value:percentChange(G.YIELD.protectedArea),label:'Leistung'};}
  if(key==='pace'&&G.paces[value].factor!==1)meta.note={value:percentChange(G.paces[value].factor),label:'Leistung'};
  if(key==='priority'&&value==='express')meta.bonus={value:G.EXPRESS.bonus,label:'Bonus'};
 }else{
  if(key==='contractType'){const c=J.contracts[value],base=J.contracts[ref];if(c.prices.saw!==base.prices.saw)meta.rate={value:c.prices.saw-base.prices.saw,per:'fm',label:'Sägeholz'};meta.risk.push({value:-c.shortfallRate,per:'fm',label:'Fehlmenge'});}
  if(key==='preparation'&&value==='records'){if(!s.boundaryChecked.a)meta.risk.push({value:-G.COSTS.boundaryIncident,label:'Grenze'});if(s.stands.some(x=>x.surveyCoverage<100))meta.risk.push({value:-G.COSTS.biotopeIncident,label:'Biotop'});}
  if(key==='documentation'&&value==='digital')meta.note={text:'spart Übergabezeit in der Ernte'};
  if(key==='haulMode'&&value==='estimate')meta.risk.push({value:-J.COSTS.tour,label:'je Leertour'});
  if(key==='access'&&value==='unchecked'&&s.stands.some(x=>x.id==='b'&&!x.closed&&x.roadside>.000001))meta.risk.push({value:-J.COSTS.failedAccess,label:'Fehlfahrt'});
  if(key==='deliveryDocs'&&value==='paper')meta.risk.push({label:'Menge hängt in Abrechnung'});
  if(key==='reconciliation'){const p=J.settlementPreview(t);if(value==='accept'&&p.openValue>0)meta.risk.push({value:-p.openValue,label:'bleibt offen'});if(value==='match'){const gain=G.round(p.invoice-J.settlementPreview(withChoice(scope,s,key,'accept')).invoice);if(gain>0)meta.bonus={value:gain,label:'abrechenbar'};}}
 }
 return meta;
}
// Signed euro text for badges: −405 € / +0 € / +6 €/fm. Signs are language-neutral; euro() formats the amount.
function signedEuro(n,per=''){const v=Math.abs(n)<.5?0:n;return (v<0?'−':'+')+euro(Math.abs(v))+(per?'/'+per:'');}
function choiceBadges(m){const tone=Math.abs(m.cost)<.5?'zero':m.cost<0?'minus':'plus';return `<span class="badge cost ${tone}" data-badge="cost">${signedEuro(m.cost)}</span>${m.risk.map(r=>`<span class="badge risk" data-badge="risk"><b>Risiko</b>${r.value===undefined?'':` <span>${signedEuro(r.value,r.per)}</span>`} <span>${r.label}</span></span>`).join('')}${m.rate?`<span class="badge rate" data-badge="rate"><span>${signedEuro(m.rate.value,m.rate.per)}</span> <span>${m.rate.label}</span></span>`:''}${m.bonus?`<span class="badge bonus" data-badge="bonus"><span>${signedEuro(m.bonus.value)}</span> <span>${m.bonus.label}</span></span>`:''}${m.note?`<span class="badge note" data-badge="note">${m.note.text||`<span>${m.note.value<0?'−':'+'}${Math.abs(m.note.value)} %</span> <span>${m.note.label}</span>`}</span>`:''}`;}
function choiceTitle(scope,key,value,title){if(key!=='contractType')return title;const c=ForestJourney.contracts[value];return `${title} · ${c.volume} / ${c.saw} fm`;}
function toggleChoice(scope,key,label){const current=scope==='journey'?state.journey[key]:state[key],options=choiceOptions[scope][key],focusable=options.some(x=>x[0]===current)?current:options[0][0];return `<fieldset class="decision-toggle" role="radiogroup" aria-labelledby="choice-${key}"><legend id="choice-${key}">${label}</legend><div class="toggle-row">${options.map(([value,title])=>{const m=choiceMeta(scope,key,value,state),on=value===current;return `<button type="button" role="radio" aria-checked="${on}" tabindex="${value===focusable?0:-1}" class="toggle${on?' on':''}" data-choice="${key}" data-scope="${scope}" value="${value}"><span class="toggle-title">${choiceTitle(scope,key,value,title)}</span><span class="toggle-badges">${choiceBadges(m)}</span><small class="toggle-why">${m.reason}</small></button>`;}).join('')}</div></fieldset>`;}
// Live planning total with a transient delta whenever the number changes within the same stage or shift.
let lastPlanTotal=null;
function planTotal(label,value,stage){const delta=lastPlanTotal&&lastPlanTotal.stage===stage?ForestGame.round(value-lastPlanTotal.value):0;lastPlanTotal={stage,value};return `<div class="plan-total" role="status"><span>${label}</span><strong data-plan-total>${euro(value)}</strong>${Math.abs(delta)>=.5?`<span class="total-delta ${delta>0?'up':'down'}" aria-hidden="true">${delta>0?'+':'−'}${euro(Math.abs(delta))}</span>`:''}</div>`;}
function applyChoice(scope,key,value){if(scope==='journey')state=ForestJourney.choose(state,key,value);else state[key]=value;}
function focusToggle(key){[...app.querySelectorAll(`[data-choice="${key}"]`)].find(el=>el.getAttribute('aria-checked')==='true')?.focus();}
// ARIA radio group: click, Enter or Space selects; arrow keys, Home and End move the selection within the group.
function bindToggles(){app.querySelectorAll('[data-scope]').forEach(el=>{const key=el.dataset.choice,scope=el.dataset.scope,pick=value=>{applyChoice(scope,key,value);render();focusToggle(key);};el.onclick=()=>pick(el.value);el.onkeydown=e=>{const group=[...app.querySelectorAll(`[data-choice="${key}"]`)].filter(x=>x.dataset.scope===scope),step={ArrowRight:1,ArrowDown:1,ArrowLeft:-1,ArrowUp:-1}[e.key];let target=null;if(e.key==='Enter'||e.key===' ')target=el;else if(step)target=group[(group.indexOf(el)+step+group.length)%group.length];else if(e.key==='Home')target=group[0];else if(e.key==='End')target=group.at(-1);if(!target)return;e.preventDefault();pick(target.value);};});}
function nextJourney(next){state=next;render();window.scrollTo({top:0,behavior:'smooth'});}
function bindJourneyMap(){app.querySelectorAll('[data-handover],[data-bio]').forEach(el=>{const open=()=>openHandover(el.dataset.handover||el.dataset.bio);el.onclick=open;el.onkeydown=e=>{if(['Enter',' '].includes(e.key)){e.preventDefault();open();}};});app.querySelectorAll('[data-plot]').forEach(el=>{const select=()=>{state.harvester=state.forwarder=el.dataset.plot;render();};el.onclick=select;el.onkeydown=e=>{if(['Enter',' '].includes(e.key)){e.preventDefault();select();}};});}
function contractCard(c){return `<section class="contract-card"><div class="contract-head"><div><p class="eyebrow">Liefervertrag · Spielauftrag</p><h2>${c.name}</h2></div><span>${c.id}</span></div><div class="contract-targets"><div><strong>${c.volume} <small>fm</small></strong><span>Mindest-Gesamtlieferung</span></div><div><strong>${c.saw} <small>fm</small></strong><span>davon Sägeholz</span></div></div><dl class="report-details"><div><dt>Lieferpunkt</dt><dd>Sägewerk / Industrieabnehmer, nach der Ernte im gebuchten Abfuhrfenster</dd></div><div><dt>Preis je fm, netto</dt><dd>${c.prices.saw} € Sägeholz · ${c.prices.pulp} € Industrieholz · ${c.prices.down} € abgewertetes Holz</dd></div><div><dt>Fehlmenge</dt><dd>${c.shortfallRate} €/fm vereinbarter Mengenausgleich im Spiel; Gesamt- und Sägeholzfehlmenge werden nicht doppelt belastet.</dd></div><div><dt>Abrechnungsbasis</dt><dd>Angeliefertes, dem Vertrag zugeordnetes Holz. Holz am Polter ist noch keine erfüllte Werkslieferung. Mehrmengen werden im Szenario zum gleichen Sortimentspreis abgenommen.</dd></div></dl></section>`;}
function renderForestPlanning(){const j=state.journey,c=ForestJourney.contracts[j.contractType],cost=ForestJourney.planPreview(state).cost;app.innerHTML=journeyHeading('Dein Auftrag beginnt im Wald.','Lege die Lieferzusage fest und entscheide, welche Informationen vor dem ersten Maschineneinsatz vorliegen.')+`<div class="journey-layout"><div>${contractCard(c)}${overviewMap()}</div><section class="journey-decisions">${planTotal('Geplante Kosten dieser Etappe',cost,'forest')}<div class="stage-card"><p class="eyebrow">01 · Waldplanung</p><h2>Was gibst du der Ernte mit?</h2>${toggleChoice('journey','contractType','Welche Menge sagst du zu?')}${toggleChoice('journey','preparation','Vorbereitung im Revier')}${toggleChoice('journey','documentation','Arbeitsauftrag bereitstellen')}</div><div class="stage-action"><b>${euro(cost)} Planungskosten</b><p>Deine Entscheidungen bestimmen die Ausgangslage für die folgenden vier Ernteschichten.</p><button class="primary" id="startHarvest">Vertrag übernehmen und Ernte planen</button></div><aside class="journey-tip"><b>Der rote Faden</b><p>Ein Auftrag, dieselben Hiebe und dieselben Mengen begleiten dich bis zur Abrechnung. Geerntet, gerückt, angeliefert und abgerechnet bleiben getrennte Zustände.</p></aside></section></div>`;bindToggles();bindJourneyMap();document.getElementById('startHarvest').onclick=()=>nextJourney(ForestJourney.start(state));}
function materialFlow(){const l=state.journey.logistics,r=state.journey.settlement;return `<div class="material-flow" aria-label="Mengen entlang der Prozesskette">${[['Waldlager',state.stands.reduce((a,x)=>a+x.stock,0),'geerntet, noch nicht gerückt'],['Am Polter',state.stands.reduce((a,x)=>a+x.roadside,0),'gerückt, noch nicht abgefahren'],['Angeliefert',l?.volume||0,'am Werk / Industrieabnehmer'],['Abrechenbar',r?Object.values(r.billable).reduce((a,x)=>a+x,0):0,'dem Vertrag zugeordnet']].map(([name,value,help])=>`<div><span>${name}</span><strong>${num(value)} <small>fm</small></strong><small>${help}</small></div>`).join('')}</div>`;}
function roadsideTable(){return `<div class="history-table-wrap"><table><thead><tr><th>Polter / Hieb</th><th>Sägeholz</th><th>Industrieholz</th><th>Abgewertet</th><th>Abfuhr</th></tr></thead><tbody>${state.stands.map(s=>`<tr><td>P-${s.id.toUpperCase()}01 · ${s.name}</td><td>${num(s.roadsideGrades.saw)} fm</td><td>${num(s.roadsideGrades.pulp)} fm</td><td>${num(s.roadsideGrades.down)} fm</td><td>${s.closed?'Gesperrt':s.roadside>.01?'Verfügbar':'Kein Bestand'}</td></tr>`).join('')}</tbody></table></div>`;}
function renderLogistics(){const p=ForestJourney.haulPreview(state);app.innerHTML=journeyHeading('Das Holz muss zum Kunden.','Plane Lkw mit dem tatsächlichen Polterbestand. Herkunft, Sortiment und Zufahrt entscheiden über eine erfolgreiche Lieferung.')+materialFlow()+`<div class="journey-layout"><div><section class="stage-card"><p class="eyebrow">03 · Polterübersicht</p><h2>${num(p.volume)} fm zur Abfuhr verfügbar</h2>${roadsideTable()}${p.blocked?`<p class="plan-error">${num(p.blocked)} fm liegen an gesperrten Hieben. Sie werden nicht verladen.</p>`:''}<p class="report-note">Nachbarholz gehört nicht zu diesen Liefermengen. Sägeholz und Industrieholz werden getrennt disponiert.</p></section><section class="stage-card"><h2>Speditionskapazität</h2><div class="fleet-mini"><div><span>L-01 / L-02 · Lkw-Pool</span><b>${p.booked} Touren gebucht</b><small>Maximal 30 Touren im gesamten Abfuhrfenster</small></div><div><span>Volumen je Tour im Spiel</span><b>bis 25 fm</b><small>Sortiment und Polter bleiben getrennt</small></div></div><p class="report-note">Vereinfachte Volumenkapazität. Reale Nutzlast, Holzfeuchte, Fahr- und Lenkzeiten werden hier nicht berechnet.</p></section></div><section class="journey-decisions">${planTotal('Geplante Kosten dieser Etappe',p.estimate,'logistics')}<div class="stage-card">${toggleChoice('journey','haulMode','Wie viele Touren bestellst du?')}${toggleChoice('journey','access','Zufahrt und Lkw-Wendepunkte')}${toggleChoice('journey','deliveryDocs','Lieferscheine und Herkunft')}</div><div class="stage-action"><b>${euro(p.estimate)} geplante Logistikkosten</b><p>${p.needed} Touren für alle verfügbaren Sortiments- und Polterpartien benötigt; ${p.booked} gebucht.</p><button class="primary" id="runHaul">Abfuhr durchführen</button></div></section></div>`;bindToggles();document.getElementById('runHaul').onclick=()=>nextJourney(ForestJourney.haul(state));}
function ledger(items){return `<dl class="cost-ledger">${items.map(x=>`<div><dt>${x.label}</dt><dd>${euro(x.value)}</dd></div>`).join('')}</dl>`;}
function deliveryTable(){return `<div class="history-table-wrap"><table><thead><tr><th>Beleg / Lkw</th><th>Herkunft</th><th>Sortiment</th><th>Menge</th><th>Status</th></tr></thead><tbody>${state.journey.logistics.loads.map(x=>`<tr><td>${x.id} · ${x.truck}</td><td>${x.polter||x.site?.toUpperCase()||'—'}</td><td>${({saw:'Sägeholz',pulp:'Industrieholz',down:'Abgewertet'})[x.grade]||'—'}</td><td>${num(x.volume)} fm</td><td>${x.missingReference?'Auftragsbezug fehlt':x.status}</td></tr>`).join('')||'<tr><td colspan="5">Keine Tour disponiert.</td></tr>'}</tbody></table></div>`;}
function renderLogisticsReceipt(){const l=state.journey.logistics;app.innerHTML=journeyHeading('Die Lieferung ist dokumentiert.','Jetzt ist sichtbar, welche Mengen beim Kunden angekommen sind und welche noch im Wald liegen.')+materialFlow()+`<div class="report-columns"><section class="stage-card"><h2>${num(l.volume)} fm angeliefert</h2><div class="event-log">${l.logs.map(x=>`<article class="log-card ${x.kind}"><b>${x.title}</b><p>${x.text}</p></article>`).join('')}</div></section><section class="stage-card"><h2>${euro(l.cost)} Logistikkosten</h2>${ledger(l.costItems)}<p class="report-note">${l.empty} gebuchte Touren ohne Holz. ${num(l.remainingRoadside)} fm verbleiben am Polter.</p></section></div><details class="stage-card"><summary>Lieferscheine und einzelne Lkw-Touren ansehen</summary>${deliveryTable()}</details><div class="actions"><button class="primary" id="toSettlement">Mengen abrechnen und Vertrag abschließen</button></div>`;document.getElementById('toSettlement').onclick=()=>nextJourney(ForestJourney.toSettlement(state));}
function renderSettlement(){const j=state.journey,p=ForestJourney.settlementPreview(state),l=j.logistics;app.innerHTML=journeyHeading('Stimmt die letzte Zahl?','Gleiche Lieferscheine und Werkbelege ab. Schließe den Auftrag mit nachvollziehbaren Restaufgaben ab.')+`<div class="journey-layout"><div>${contractCard(j.contract)}<section class="stage-card"><p class="eyebrow">04 · Abrechnungsprüfung</p><h2>Eine Abweichung braucht eine Entscheidung.</h2><div class="reconcile-row"><span>Sägeholz laut Lieferscheinen</span><b>${num(l.delivered.saw)} fm</b></div><div class="reconcile-row"><span>Sägeholz laut vorläufigem Werkbeleg</span><b>${num(Math.max(0,l.delivered.saw-p.error))} fm</b></div><p>${p.error?`${num(p.error)} fm sind im Prüfszenario dem falschen Auftrag zugeordnet. Ein Belegabgleich kann die Zuordnung korrigieren.`:'Keine Sägeholzlieferung vorhanden; kein Zuordnungsfehler im Werkbeleg.'}</p>${l.loads.some(x=>x.missingReference)?'<p class="plan-error">Zusätzlich fehlt auf einem Papierlieferschein der Auftragsbezug.</p>':''}<p class="report-note">Dies ist ein Zuordnungsfall, kein automatischer Aufschlag bei echter Messdifferenz. Reale Abweichungen brauchen einen nachvollziehbaren Nachweis.</p></section><details class="stage-card"><summary>Lieferbelege ansehen</summary>${deliveryTable()}</details></div><section class="journey-decisions">${planTotal('Geplante Kosten dieser Etappe',p.cost,'settlement')}<div class="stage-card">${toggleChoice('journey','reconciliation','Mengen und Belege abgleichen')}${toggleChoice('journey','closeout','Wie schließt du den Vertrag ab?')}</div><div class="stage-action"><span>Voraussichtlich abrechenbar</span><b>${euro(p.invoice)}</b><p>${euro(p.openValue)} bis zur Belegklärung offen · ${euro(p.shortfallCost)} vereinbarter Mengenausgleich.</p><p><strong>${p.status}</strong></p><button class="primary" id="settleContract">Im Spiel abrechnen und abschließen</button><small>Simulation · keine reale Rechnung oder Vertragsänderung</small></div></section></div>`;bindToggles();document.getElementById('settleContract').onclick=()=>nextJourney(ForestJourney.settle(state));}
function renderJourneyResult(){const j=state.journey,r=j.settlement,l=j.logistics,score=ForestJourney.score(state),parts=ForestJourney.breakdown(state),opps=opportunities();app.innerHTML=journeyHeading('Vom Wald bis zum Abschluss.','So wirken deine Entscheidungen entlang der gesamten Prozesskette.')+`<section class="receipt final-score"><div class="summary"><div class="score"><strong>${score}</strong><span>von 1.000 Punkten</span></div><div><p class="eyebrow">${r.status}</p><h2>${euro(r.margin)} Wertbeitrag im Spiel</h2><p>${num(l.volume)} / ${j.contract.volume} fm angeliefert · ${num(l.delivered.saw)} / ${j.contract.saw} fm Sägeholz.</p><p>${euro(r.invoice)} abgerechnet · ${euro(r.openValue)} bis zur Klärung offen.</p>${previousResult?`<p class="previous-score">Vorherige Reise: ${previousResult.score} Punkte · jetzt ${score-previousResult.score>=0?'+':''}${score-previousResult.score} Punkte.</p>`:''}</div></div><div class="score-breakdown journey-score">${parts.map(p=>`<div><b>${p.name}</b><strong>${p.points}<small> / ${p.max}</small></strong><div class="meter"><i style="width:${p.points/p.max*100}%"></i></div><p>${p.detail}</p></div>`).join('')}</div></section>${materialFlow()}<div class="report-columns"><section class="stage-card"><h2>Auftrag ${j.contract.id} · Schlussübersicht</h2>${ledger([{label:'Abrechenbarer Holzwert',value:r.invoice},{label:'Erreichter Bereitstellungsbonus',value:r.bonus},{label:'Waldplanung',value:-j.plan.cost},{label:'Holzernte und Maschineneinsatz',value:-state.history.reduce((a,x)=>a+x.cost,0)},{label:'Lkw-Logistik',value:-l.cost},{label:'Abrechnung und Mengenausgleich',value:-r.cost},{label:'Wertbeitrag',value:r.margin}])}<p class="report-note">Keine doppelte Erlösbuchung: Der frühere Polterwert war vorläufig. Jetzt zählt der abrechenbare Lieferwert. Holzeinkauf, Kulturkosten, Gemeinkosten und Steuern sind nicht enthalten.</p></section><section class="stage-card"><h2>Was bleibt zu übergeben?</h2><ul class="closeout-list"><li>${num(r.shortfall)} fm Vertragsfehlmenge · ${euro(r.shortfallCost)} Mengenausgleich</li><li>${num(state.stands.reduce((a,x)=>a+x.stock,0))} fm Waldlager und ${num(l.remainingRoadside)} fm Polterbestand</li><li>${state.closedSites.length} gesperrte Hiebe · ${num(state.neighbourVolume)} fm Nachbarholz gesondert</li><li>${r.matched?'Liefer- und Werkbelege abgeglichen.':r.issues.join(' ')||'Keine Belegabweichung festgestellt.'}</li><li>${r.status}</li></ul><p class="report-note">Ein dokumentierter Teilabschluss beseitigt keine Sperre und ersetzt keine Klärung eines Schadens. Restaufgaben gehen nachvollziehbar an den Auftraggeber.</p></section></div><section class="conversation"><p class="eyebrow">Gespräch am Messestand</p><h2>„Wo geht bei euch die Verbindung zwischen Hiebsauftrag, Polter, Lieferung und Abrechnung verloren?“</h2><p>${opps[0].question}</p></section><div class="cf-connections"><article><p class="eyebrow">Planung & Holzernte</p><h3>Gemeinsamer Auftrag, gemeinsame Informationen</h3><p>Das CFHarvest-Datenblatt beschreibt Arbeitsgebiete mit Vertragsinformationen, Produkten, Lieferungen, Karten und laufenden Produktionsmeldungen.</p></article><article><p class="eyebrow">Logistik & Abschluss</p><h3>Daten weitergeben, Mengen nachvollziehen</h3><p>Im Spiel nutzen die Folgeprozesse dieselbe Herkunft und dieselben Mengen. Lkw-Disposition, Rechnung und Vertragsabschluss sind ergänzende Spielszenarien; das verwendete Datenblatt weist sie nicht als eigenständige CFHarvest-Abrechnungsmodule aus.</p></article></div><details class="stage-card"><summary>Ernteschichten und Punktelogik ansehen</summary><div class="history-table-wrap"><table><thead><tr><th>Schicht</th><th>Geerntet</th><th>Gerückt</th><th>Abgewertet</th><th>Einsatzkosten</th></tr></thead><tbody>${state.history.map(x=>`<tr><td>${x.round}</td><td>${num(x.harvest)} fm</td><td>${num(x.forwarded)} fm</td><td>${num(x.downgraded)} fm</td><td>${euro(x.cost)}</td></tr>`).join('')}</tbody></table></div><p>Waldplanung 100, Holzernte 500, Logistik 200, Abrechnung und Vertrag 200 Punkte. Die Holzernte übernimmt die bisherige Bewertung mit halbem Gewicht; ihr Stand wird vor der Abfuhr festgehalten. Logistik bewertet Werkslieferung und Tourennutzung. Abrechnung bewertet abrechenbare Mengen, Prüfung und dokumentierten Abschluss.</p></details><div class="actions"><button class="primary" id="improve">Gesamte Reise mit besserer Planung wiederholen</button><button class="secondary" id="restart">Nächster Gast · neu beginnen</button></div><p class="source-note">Produktbezug: <a href="assets/CFHarvest-SpecSheet.pdf" target="_blank" rel="noopener">Trimble CFHarvest Datenblatt · 03/2026</a>. Sämtliche Preise, Verträge, Touren und Vorfälle sind Spielannahmen.</p>`;document.getElementById('improve').onclick=()=>{previousResult={score};nextJourney(ForestJourney.initial(true));};document.getElementById('restart').onclick=()=>{previousResult=null;nextJourney(ForestJourney.initial());};}
